`timescale 1ns/1ps
// Replays vectors.mem (generated by verilog_xlat.py) against secded_enc / secded_dec.
// Each line is 9 hex digits: data(2) err(4) expected_data_out(2) flags(1) with flags = {corrected, uncorrectable}.
module secded_vec_tb;
    reg  [35:0] mem [0:23551];
    reg  [7:0]  data;
    reg  [15:0] e16;
    reg  [7:0]  exp_d;
    reg  [3:0]  fl;
    reg  [12:0] err;
    wire [12:0] code, code_rx;
    wire [7:0]  data_out;
    wire        corrected, uncorrectable;
    integer n, fails;

    secded_enc enc (.data(data), .code(code));
    assign code_rx = code ^ err;
    secded_dec dec (.code_in(code_rx), .data_out(data_out),
                    .corrected(corrected), .uncorrectable(uncorrectable));

    initial begin
        fails = 0;
        $readmemh("vectors.mem", mem);
        for (n = 0; n < 23552; n = n + 1) begin
            {data, e16, exp_d, fl} = mem[n];
            err = e16[12:0];
            #1;
            if (data_out !== exp_d || corrected !== fl[1] || uncorrectable !== fl[0]) begin
                fails = fails + 1;
                if (fails <= 10)
                    $display("MISMATCH line %0d: data=%h err=%h got out=%h c=%b u=%b, exp out=%h c=%b u=%b",
                             n, data, err, data_out, corrected, uncorrectable, exp_d, fl[1], fl[0]);
            end
        end
        $display("vectors checked: 23552, mismatches: %0d", fails);
        $finish;
    end
endmodule
